import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse(`{"title":"Collection","description":"Collection en allemand de documentations maintenues concernant Home Assistant, HACS et l'Open Source.","frontmatter":{"title":"Collection","description":"Collection en allemand de documentations maintenues concernant Home Assistant, HACS et l'Open Source."},"headers":[],"relativePath":"fr/collection/index.md","filePath":"fr/collection/index.md","lastUpdated":1793123358000}`),o={name:"fr/collection/index.md"};function i(r,e,l,d,c,u){return a(),n("div",null,[...e[0]||(e[0]=[s('<p><a id="collection"></a><a id="orientation-actuelle"></a></p><h1 id="sammlung" tabindex="-1">Collection <a class="header-anchor" href="#sammlung" aria-label="Permalink to &quot;Collection {#sammlung}&quot;">​</a></h1><p>Cette collection regroupe des documentations, des exemples et des pages de projet maintenus en allemand, portant sur Home Assistant, HACS et l&#39;Open Source.</p><p>Cette collection est issue de ma documentation personnelle. Elle a été créée à l&#39;origine pour un cercle d&#39;amis et de connaissances qui s&#39;intéressent à Home Assistant, mais qui possèdent peu ou pas de connaissances en anglais. La documentation privée initiale a ensuite été comparée aux documents originaux respectifs à l&#39;aide de ChatGPT. Ce processus a permis de corriger les erreurs identifiées, de supprimer les formulations obsolètes et de clarifier les passages ambigus.</p><p>L&#39;accent est mis sur des documents exploitables en pratique, incluant la version, la source originale, la mention de licence et des exemples. Les projets externes sont identifiés comme des traductions non officielles ou des documents de travail complémentaires.</p><h2 id="bereiche" tabindex="-1">Zones <a class="header-anchor" href="#bereiche" aria-label="Permalink to &quot;Zones {#bereiche}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domaine</th><th>Contenu</th></tr></thead><tbody><tr><td><a href="/fr/collection/ha-recommendations">Recommandations HA</a></td><td>Liens sélectionnés vers des cartes (cards), intégrations, applications et outils disposant d&#39;une documentation en français ou offrant une bonne porte d&#39;entrée.</td></tr><tr><td><a href="/fr/collection/ha-cards">Cartes HA</a></td><td>Cartes Lovelace et HACS accompagnées d&#39;instructions en allemand et d&#39;exemples.</td></tr><tr><td><a href="/fr/collection/ha-dashboard">Tableaux de bord HA</a></td><td>Thèmes, idées de mise en page et extensions visuelles pour les tableaux de bord Home Assistant.</td></tr><tr><td><a href="/fr/collection/ha-integrations">Intégrations HA</a></td><td>Intégrations personnalisées (custom integrations) et intégrations HACS pour Home Assistant.</td></tr><tr><td><a href="/fr/collection/ha-blueprints">Blueprints HA</a></td><td>Modèles d&#39;automatisation (blueprints) et modèles réutilisables pour Home Assistant.</td></tr><tr><td><a href="/fr/collection/ha-tools">Outils HA</a></td><td>Outils externes liés à Home Assistant, aux tableaux de bord et au développement.</td></tr><tr><td><a href="/fr/collection/ha-apps">Applications HA</a></td><td>Modules complémentaires (add-ons), ponts MQTT et services en cours d&#39;exécution pour Home Assistant.</td></tr><tr><td><a href="/fr/collection/hacs-docs">Documentation HACS</a></td><td>Espace regroupant des projets HACS externes qui ne sont pas clairement classables comme des cartes (cards) ou des intégrations.</td></tr><tr><td><a href="/fr/collection/interesting-examples">Autres exemples intéressants</a></td><td>Exemples issus de la communauté externe, Gists et idées qui ne sont volontairement pas intégrés à la documentation spécifique des projets.</td></tr></tbody></table><h2 id="separat-gepflegt" tabindex="-1">Maintenu séparément <a class="header-anchor" href="#separat-gepflegt" aria-label="Permalink to &quot;Maintenu séparément {#separat-gepflegt}&quot;">​</a></h2><p>UIX est volontairement exclu de cette collection, car la documentation allemande d&#39;UIX est déjà maintenue séparément et référencée dans le menu de sélection de langue officiel d&#39;UIX.</p><ul><li><a href="/fr/projects/uix/">Ouvrir la documentation allemande d&#39;UIX</a></li><li><a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">Ouvrir la documentation originale d&#39;UIX</a></li></ul><h2 id="grundregeln" tabindex="-1">Règles fondamentales <a class="header-anchor" href="#grundregeln" aria-label="Permalink to &quot;Règles fondamentales {#grundregeln}&quot;">​</a></h2><ul><li>La source originale et la licence sont indiquées de manière visible pour chaque document.</li><li>Pour les projets externes, la documentation originale fait foi.</li><li>Les exemples doivent être complets et immédiatement utilisables.</li><li>Les contenus obsolètes sont signalés comme tels.</li><li>Des mentions relatives à l&#39;IA ou aux agents sont ajoutées via des métadonnées ou <code>llms.txt</code>, lorsque cela s&#39;avère pertinent.</li></ul>',12)])])}const f=t(o,[["render",i]]);export{p as __pageData,f as default};
